<script setup>
import { onMounted, reactive, ref, watch } from 'vue';
import ReturnActionModal from '../../components/returns/ReturnActionModal.vue';
import { useReturnStore } from '../../stores/return';

const store = useReturnStore(); const filters = reactive({ search: '', reason: '', status: '', hub_id: '', page: 1, per_page: 15 }); const selected = ref(null); let timer;
const badge = { pending_intake: 'bg-amber-100 text-amber-800', in_reverse_queue: 'bg-blue-100 text-blue-800', reattempt_scheduled: 'bg-teal-100 text-teal-800', rts_in_transit: 'bg-purple-100 text-purple-800', rts_completed: 'bg-slate-100 text-slate-700', disposed: 'bg-red-100 text-red-800' }; const label = (value) => value?.replaceAll('_', ' ');
const load = () => store.fetchReturns({ ...filters, reason: filters.reason || undefined, status: filters.status || undefined, hub_id: filters.hub_id || undefined }); const search = () => { clearTimeout(timer); timer = setTimeout(() => { filters.page = 1; load(); }, 300); }; const processed = () => { selected.value = null; load(); };
watch(() => [filters.reason, filters.status, filters.hub_id], () => { filters.page = 1; load(); }); onMounted(load);
</script>

<template>
  <main class="min-h-screen bg-[#f4f7f6] text-slate-900"><header class="border-b border-slate-200 bg-white"><div class="mx-auto max-w-7xl px-6 py-6"><p class="text-xs font-black uppercase tracking-[0.22em] text-teal-700">Reverse logistics</p><div class="mt-1 flex flex-wrap items-center justify-between gap-4"><div><h1 class="text-3xl font-black">Return intake queue</h1><p class="mt-1 text-sm text-slate-500">Review failed deliveries and choose the next disposition.</p></div><span class="text-sm font-semibold text-slate-500">{{ store.returns.total }} returns</span></div></div></header><div class="mx-auto max-w-7xl px-6 py-8"><section class="border border-slate-200 bg-white shadow-sm"><div class="grid gap-3 border-b border-slate-200 p-5 md:grid-cols-3"><input v-model="filters.search" @input="search" placeholder="Search AWB or recipient" class="border px-3 py-2 text-sm" /><select v-model="filters.reason" class="border px-3 py-2 text-sm"><option value="">All reasons</option><option v-for="reason in ['failed_delivery_3x','customer_refused','incorrect_address','damaged_goods','expired_holding']" :key="reason" :value="reason">{{ label(reason) }}</option></select><select v-model="filters.status" class="border px-3 py-2 text-sm"><option value="">All return statuses</option><option v-for="status in Object.keys(badge)" :key="status" :value="status">{{ label(status) }}</option></select></div><div v-if="store.error" class="m-5 bg-red-50 px-4 py-3 text-sm text-red-700">{{ store.error }}</div><div class="overflow-x-auto"><table class="w-full min-w-[850px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">AWB / recipient</th><th class="px-5 py-3">Reason</th><th class="px-5 py-3">Hub</th><th class="px-5 py-3">Logged</th><th class="px-5 py-3">Status</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in store.returns.data" :key="item.id" class="hover:bg-teal-50/30"><td class="px-5 py-4"><strong class="font-mono">{{ item.order?.awb_number }}</strong><span class="block text-slate-500">{{ item.order?.recipient_name }}</span></td><td class="px-5 py-4 capitalize">{{ label(item.return_reason) }}</td><td class="px-5 py-4 text-slate-600">{{ item.order?.current_hub?.name || item.order?.hub?.name || '—' }}</td><td class="px-5 py-4 text-slate-500">{{ item.created_at ? new Date(item.created_at).toLocaleDateString() : '—' }}</td><td class="px-5 py-4"><span class="px-2.5 py-1 text-xs font-bold capitalize" :class="badge[item.status]">{{ label(item.status) }}</span></td><td class="px-5 py-4 text-right"><button v-if="!['disposed','rts_completed'].includes(item.status)" class="font-bold text-teal-700" @click="selected = item">Process decision</button><span v-else class="text-slate-400">Closed</span></td></tr><tr v-if="!store.loading && !store.returns.data.length"><td colspan="6" class="p-12 text-center text-slate-400">No returns match these filters.</td></tr></tbody></table></div><footer class="flex justify-between border-t p-4 text-sm text-slate-500"><span>Page {{ store.returns.current_page }} of {{ store.returns.last_page }}</span><div class="flex gap-2"><button :disabled="filters.page <= 1" class="border px-3 py-1 disabled:opacity-40" @click="filters.page--; load()">Previous</button><button :disabled="filters.page >= store.returns.last_page" class="border px-3 py-1 disabled:opacity-40" @click="filters.page++; load()">Next</button></div></footer></section></div><ReturnActionModal v-if="selected" :return-item="selected" @close="selected = null" @processed="processed" /></main>
</template>